import { describe, expect, it } from 'vitest';
import { makeBargeInDetector } from './listen';
import { resampleTo16k } from './transcribe';

describe('makeBargeInDetector', () => {
  it('triggers after sustained loud input', () => {
    const d = makeBargeInDetector({ noise: 0.01, holdMs: 400 });
    expect(d(0.2, 100)).toBe(false);
    expect(d(0.2, 100)).toBe(false);
    expect(d(0.2, 100)).toBe(false);
    expect(d(0.2, 100)).toBe(true);
  });

  it('ignores short spikes', () => {
    const d = makeBargeInDetector({ noise: 0.01, holdMs: 400 });
    for (let i = 0; i < 10; i++) {
      expect(d(0.2, 100)).toBe(false);
      expect(d(0.0, 100)).toBe(false);
    }
  });

  it('respects the noise floor (threshold = max(0.07, noise × 4))', () => {
    const quiet = makeBargeInDetector({ noise: 0.01, holdMs: 200 });
    expect([quiet(0.06, 100), quiet(0.06, 100), quiet(0.06, 100)]).toEqual([false, false, false]);
    const noisy = makeBargeInDetector({ noise: 0.05, holdMs: 200 });
    expect([noisy(0.15, 100), noisy(0.15, 100), noisy(0.15, 100)]).toEqual([false, false, false]);
    expect([noisy(0.25, 100), noisy(0.25, 100)]).toEqual([false, true]);
  });
});

describe('resampleTo16k', () => {
  it('returns the same array at 16 kHz', () => {
    const input = new Float32Array([1, 2, 3, 4]);
    expect(resampleTo16k(input, 16000)).toBe(input);
  });

  it('halves the length from 32 kHz', () => {
    expect(resampleTo16k(new Float32Array(32000), 32000).length).toBe(16000);
  });

  it('keeps a constant signal constant', () => {
    const out = resampleTo16k(new Float32Array(480).fill(0.5), 48000);
    expect(out.every((v) => Math.abs(v - 0.5) < 1e-6)).toBe(true);
  });

  it('gives 1600 samples for 4800 samples at 48 kHz', () => {
    expect(resampleTo16k(new Float32Array(4800), 48000).length).toBe(1600);
  });
});
